const body = $json.body;
const event = (body.events && body.events[0]) || {};
const eventType = event.type;
const userId = event.source && event.source.userId;
const replyToken = event.replyToken;
// Quality test messages never execute transactional intents. Authorization is checked in the assistant.
const qualityRaw = eventType === 'message' && event.message && event.message.type === 'text' ? String(event.message.text || '').trim() : '';
if (/^ทดสอบ(?:บทบาท)?(?:\s|[:：]|$)/.test(qualityRaw)) {
  return [{json:{userId,replyToken,text:'ทดสอบบทบาท',quality_test_text:qualityRaw,eventType,intent:'unknown',route:'fallback',category:null,isValidCategory:false}}];
}

function parseQueryString(str) {
  const params = {};
  const parts = (str || '').split('&');
  for (const part of parts) {
    const idx = part.indexOf('=');
    if (idx === -1) continue;
    const key = decodeURIComponent(part.slice(0, idx));
    const val = decodeURIComponent(part.slice(idx + 1));
    params[key] = val;
  }
  return params;
}
function getField(text, label) {
  const re = new RegExp(label + '\\s*[:\uFF1A]\\s*(.+)');
  const m = text.match(re);
  return m ? m[1].trim() : '';
}
const textToCategory = { 'สั่งอาหาร/ของแห้ง':'food', 'เรียกรถ/ส่งคน':'ride', 'จ้างรถ-เครื่องจักรเกษตร':'agri' };
const categoryToOrderType = { food:'food', ride:'ride', agri:'agri_service' };
const categoryLabelTh = { food:'สั่งอาหาร/ของแห้ง', ride:'เรียกรถ/ส่งคน', agri:'จ้างรถ-เครื่องจักรเกษตร' };
const vehicleMap = { 'มอเตอร์ไซค์':'motorcycle','จักรยานยนต์':'motorcycle','รถกระบะ':'pickup','กระบะ':'pickup','สามล้อ':'trike','รถอีแต๋น':'tractor','อีแต๋น':'tractor','รถไถ':'tractor','จักรยาน':'bicycle','รถเก็บเกี่ยว':'harvester','รถเกี่ยวข้าว':'harvester','รถดำนา':'rice_transplanter','โดรน':'drone','รถยนต์':'car','รถ':'other' };
function mapVehicle(text) { for (const key in vehicleMap) { if (text.indexOf(key) !== -1) return vehicleMap[key]; } return 'other'; }

let intent = 'unknown', category = null, text = '';
let jobKind = null;
let latitude = null, longitude = null, locationAddress = null;
let messageId = null;
let placeCategory = null;
let ratingScore = null;
let raksAction = null;
let raksProfileId = null;
let raksWebAppId = null;
let raksRole = null;
if (eventType === 'postback' && event.postback && event.postback.data) {
  const params = parseQueryString(event.postback.data);
  if (params.raksAction) { raksAction = params.raksAction; raksProfileId = params.raksProfileId || null; raksWebAppId = params.raksWebAppId || null; raksRole = params.raksRole || null; }
  if (params.action === 'start_order') { category = params.category; intent = 'order'; }
} else if (eventType === 'message' && event.message && event.message.type === 'image') {
  intent = 'product_photo';
  messageId = event.message.id;
} else if (eventType === 'message' && event.message && event.message.type === 'location') {
  intent = 'location_share';
  latitude = event.message.latitude;
  longitude = event.message.longitude;
  locationAddress = event.message.address || event.message.title || null;
} else if (eventType === 'message' && event.message && event.message.type === 'text') {
  text = event.message.text || '';
  const trimmed = text.trim();
  const hasNameField = trimmed.indexOf('ชื่อ-นามสกุล') !== -1 || trimmed.indexOf('ชื่อนามสกุล') !== -1;
  if (textToCategory[trimmed]) { category = textToCategory[trimmed]; intent = 'order'; }
  else if (trimmed === 'สมัครร้านค้า') { intent = 'merchant_start'; }
  else if (trimmed.indexOf('สมัครร้านค้า') === 0 && trimmed.indexOf('ชื่อร้าน') !== -1) { intent = 'merchant_submit'; }
  else if (trimmed === 'สมัครไรเดอร์') { intent = 'driver_start'; jobKind = 'motorcycle'; }
  else if (trimmed === 'สมัครขับรถส่วนตัว' || trimmed === 'สมัครรถส่วนบุคคล') { intent = 'driver_start'; jobKind = 'personal'; }
  else if (trimmed === 'สมัครงาน' || trimmed === 'สมัครงานอาชีพ') { intent = 'jobseeker_start'; }
  else if (trimmed === 'สถานที่สำคัญ') { intent = 'places_menu'; }
  else if (trimmed === 'สถานที่ราชการ') { intent = 'browse_places'; placeCategory = 'government'; }
  else if (trimmed === 'โรงพยาบาล') { intent = 'browse_places'; placeCategory = 'hospital'; }
  else if (trimmed === 'โรงเรียน') { intent = 'browse_places'; placeCategory = 'school'; }
  else if (trimmed === 'มหาวิทยาลัย') { intent = 'browse_places'; placeCategory = 'university'; }
  else if (trimmed === 'วัด') { intent = 'browse_places'; placeCategory = 'temple'; }
  else if (/^(นโยบายความเป็นส่วนตัว|ความเป็นส่วนตัว|PDPA|ข้อมูลส่วนบุคคล)$/i.test(trimmed)) { intent = 'privacy_policy'; }
  else if (trimmed === 'สมัครรถไถ') { intent = 'driver_start'; jobKind = 'tractor'; }
  else if (trimmed === 'สมัครรถเกี่ยวข้าว') { intent = 'driver_start'; jobKind = 'harvester'; }
  else if (trimmed === 'สมัครรถดำนา') { intent = 'driver_start'; jobKind = 'rice_transplanter'; }
  else if (trimmed === 'สมัครโดรน') { intent = 'driver_start'; jobKind = 'drone'; }
  else if ((trimmed.indexOf('สมัครขับรถส่วนตัว') === 0 || trimmed.indexOf('สมัครรถส่วนบุคคล') === 0) && hasNameField) { intent = 'driver_submit'; jobKind = 'personal'; }
  else if (trimmed.indexOf('สมัครรถไถ') === 0 && hasNameField) { intent = 'driver_submit'; jobKind = 'tractor'; }
  else if (trimmed.indexOf('สมัครรถเกี่ยวข้าว') === 0 && hasNameField) { intent = 'driver_submit'; jobKind = 'harvester'; }
  else if (trimmed.indexOf('สมัครรถดำนา') === 0 && hasNameField) { intent = 'driver_submit'; jobKind = 'rice_transplanter'; }
  else if (trimmed.indexOf('สมัครโดรน') === 0 && hasNameField) { intent = 'driver_submit'; jobKind = 'drone'; }
  else if (trimmed.indexOf('สมัครไรเดอร์') === 0 && hasNameField) { intent = 'driver_submit'; jobKind = 'motorcycle'; }
  else if (trimmed.indexOf('สมัครงาน') === 0 && hasNameField) { intent = 'jobseeker_submit'; }
  else if (trimmed === 'เพิ่มสินค้า') { intent = 'product_start'; }
  else if (trimmed.indexOf('เพิ่มสินค้า') === 0 && trimmed.indexOf('ชื่อสินค้า') !== -1) { intent = 'product_pending_submit'; }
  else if (/^(ยืนยันรับของ|ได้รับของแล้ว|ได้รับแล้ว|ยืนยันรับสินค้า|ปิดงาน)$/.test(trimmed)) { intent = 'confirm_receipt'; }
  else if (/^[1-5]$/.test(trimmed)) { intent = 'rating_input_candidate'; ratingScore = parseInt(trimmed, 10); }
  else if (/^(สรุปยอดวันนี้|ยอดวันนี้|สรุปยอด)$/.test(trimmed)) { intent = 'daily_summary_request'; }
  else if (/^(อันดับ|จัดอันดับ|อันดับความพึงพอใจ|ท็อปไรเดอร์|ท็อปร้านค้า)$/.test(trimmed)) { intent = 'ranking_request'; }
}

const orderType = category ? categoryToOrderType[category] : null;
const isValidCategory = intent === 'order' && !!orderType;

let route = 'fallback';
if (intent === 'order' && isValidCategory) route = 'upsert';
else if (intent === 'merchant_submit') route = 'upsert';
else if (intent === 'driver_submit') route = 'upsert';
else if (intent === 'merchant_start') route = 'merchant_start';
else if (intent === 'driver_start') route = 'driver_start';
else if (intent === 'product_start') route = 'product_start';
else if (intent === 'product_pending_submit') route = 'product_pending_submit';
else if (intent === 'product_photo') route = 'product_photo';
else if (intent === 'jobseeker_start') route = 'jobseeker_start';
else if (intent === 'jobseeker_submit') route = 'jobseeker_submit';
else if (intent === 'places_menu') route = 'places_menu';
else if (intent === 'browse_places') route = 'browse_places';

let profileRole = 'customer', profileFullName = 'ลูกค้า LINE', profilePhone = null, profilePromptpay = null, profileApproved = true;
let merchantName = '', merchantCategory = '', merchantAddress = '';
let vehicleTypeEnum = 'motorcycle';
let pendingItemName = '', pendingItemPrice = 0;
let jobseekerFullName = '', jobseekerOccupation = '', jobseekerSkills = '', jobseekerPhone = '', jobseekerArea = '';

const presetVehicleByJobKind = { tractor: 'tractor', harvester: 'harvester', rice_transplanter: 'rice_transplanter', drone: 'drone', motorcycle: 'motorcycle' };

if (intent === 'merchant_submit') {
  profileRole = 'merchant'; profileApproved = false;
  merchantName = getField(text, 'ชื่อร้าน'); merchantCategory = getField(text, 'ประเภทร้าน') || getField(text, 'ประเภท'); merchantAddress = getField(text, 'ที่อยู่');
  profilePhone = getField(text, 'เบอร์โทร') || null; profilePromptpay = getField(text, 'พร้อมเพย์') || null;
  profileFullName = merchantName || 'ร้านค้าใหม่';
} else if (intent === 'driver_submit') {
  profileRole = 'driver'; profileApproved = false;
  profileFullName = getField(text, 'ชื่อ-นามสกุล') || getField(text, 'ชื่อนามสกุล') || 'ไรเดอร์ใหม่';
  profilePhone = getField(text, 'เบอร์โทร') || null; profilePromptpay = getField(text, 'พร้อมเพย์') || null;
  if (jobKind && presetVehicleByJobKind[jobKind]) {
    vehicleTypeEnum = presetVehicleByJobKind[jobKind];
  } else {
    const vehicleText = getField(text, 'ประเภทพาหนะ') || getField(text, 'ประเภทรถ') || getField(text, 'พาหนะ');
    vehicleTypeEnum = mapVehicle(vehicleText);
  }
} else if (intent === 'product_pending_submit') {
  pendingItemName = getField(text, 'ชื่อสินค้า');
  const priceRaw = getField(text, 'ราคา');
  pendingItemPrice = parseFloat(priceRaw.replace(/[^0-9.]/g, '')) || 0;
} else if (intent === 'jobseeker_submit') {
  jobseekerFullName = getField(text, 'ชื่อ-นามสกุล') || getField(text, 'ชื่อนามสกุล') || 'ไม่ระบุชื่อ';
  jobseekerOccupation = getField(text, 'อาชีพ');
  jobseekerSkills = getField(text, 'ความรู้ความสามารถ') || getField(text, 'ความรู้') || getField(text, 'ประสบการณ์');
  jobseekerPhone = getField(text, 'เบอร์โทร') || null;
  jobseekerArea = getField(text, 'พื้นที่') || getField(text, 'พื้นที่ทำงาน');
}

let instructionText = '';
if (intent === 'merchant_start') {
  instructionText = 'ยินดีต้อนรับร้านค้าเข้าร่วมกับเราครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับร้านของท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยนะครับ\n\nสมัครร้านค้า\nชื่อร้าน: (ชื่อร้านของท่าน)\nประเภทร้าน: (เช่น ร้านอาหาร, ร้านของแห้ง, ร้านทำฟัน, ร้านซ่อมรถ, ร้านเสริมสวย ฯลฯ)\nที่อยู่: (ที่อยู่ร้าน)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nพร้อมเพย์: (เลขพร้อมเพย์)';
} else if (intent === 'driver_start') {
  if (jobKind === 'motorcycle') {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครไรเดอร์\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nพร้อมเพย์: (เลขพร้อมเพย์)\n\n(สำหรับมอเตอร์ไซค์เท่านั้น)';
  } else if (jobKind === 'personal') {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครรถส่วนบุคคล\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nประเภทรถ: รถยนต์ หรือ รถกระบะ\nพร้อมเพย์: (เลขพร้อมเพย์)\n\n(สำหรับส่งคนและส่งของด้วยรถยนต์หรือรถกระบะ)';
  } else if (jobKind === 'tractor') {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครรถไถ\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nพร้อมเพย์: (เลขพร้อมเพย์)';
  } else if (jobKind === 'harvester') {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครรถเกี่ยวข้าว\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nพร้อมเพย์: (เลขพร้อมเพย์)';
  } else if (jobKind === 'rice_transplanter') {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครรถดำนา\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nพร้อมเพย์: (เลขพร้อมเพย์)';
  } else if (jobKind === 'drone') {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครโดรน\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nพร้อมเพย์: (เลขพร้อมเพย์)';
  } else {
    instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครไรเดอร์\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nเบอร์โทร: (เบอร์โทรติดต่อ)\nประเภทพาหนะ: มอเตอร์ไซค์ / รถยนต์ / รถกระบะ / สามล้อ / รถอีแต๋น / อื่นๆ\nพร้อมเพย์: (เลขพร้อมเพย์)';
  }
} else if (intent === 'jobseeker_start') {
  instructionText = 'ขอบคุณที่สนใจสมัครกับเรานะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ\n\nสมัครงานอาชีพ\nชื่อ-นามสกุล: (ชื่อจริง นามสกุล)\nอาชีพ: (เช่น ช่างไฟฟ้า, แม่บ้าน, กรรมกร, พนักงานทั่วไป ฯลฯ)\nความรู้ความสามารถ: (ความรู้ ความสามารถ ประสบการณ์ วุฒิการศึกษา ฯลฯ)\nพื้นที่: (พื้นที่ที่สะดวกทำงาน)\nเบอร์โทร: (เบอร์โทรติดต่อ)';
} else if (intent === 'privacy_policy') {
  instructionText = 'นโยบายความเป็นส่วนตัว (PDPA)\n\nเราเก็บข้อมูลของท่านเท่าที่จำเป็นสำหรับให้บริการนี้เท่านั้น ได้แก่ ชื่อ เบอร์โทร ที่อยู่หรือตำแหน่ง GPS เลขพร้อมเพย์ ประวัติการสั่งของ และคะแนนความพึงพอใจ\n\nวัตถุประสงค์: ใช้เพื่อจับคู่ร้านค้า ไรเดอร์ และลูกค้า คำนวณค่าส่ง ติดต่อประสานงาน รับชำระเงินผ่านบัญชีตัวแทนตำบล และโอนส่วนแบ่งให้ร้านค้า/ไรเดอร์ผ่านพร้อมเพย์\n\nการเข้าถึงข้อมูล: เฉพาะเจ้าของข้อมูลและผู้ดูแลระบบเท่านั้น ไม่เปิดเผยต่อสาธารณะ ไม่ขายหรือส่งต่อให้บุคคลภายนอกใดๆ\n\nสิทธิของท่าน: ขอดู แก้ไข หรือขอให้ลบข้อมูลได้ทุกเมื่อ โดยติดต่อผู้ดูแลระบบโดยตรงครับ';
} else if (intent === 'places_menu') {
  instructionText = 'อยากดูข้อมูลสถานที่ไหนในตำบล พิมพ์ชื่อหมวดด้านล่างมาได้เลยครับ:\n- สถานที่ราชการ\n- โรงพยาบาล\n- โรงเรียน\n- มหาวิทยาลัย\n- วัด';
} else if (intent === 'product_start') {
  instructionText = 'รับข้อมูลสินค้าให้เลยนะครับ รบกวนคัดลอกข้อความด้านล่าง แก้ไขข้อมูลให้ตรงกับสินค้าของท่าน แล้วส่งกลับมาในข้อความเดียวได้เลยครับ จากนั้นส่ง "รูปสินค้า" ตามมาเป็นข้อความถัดไปได้ทันที (1 รูปต่อ 1 รายการ)\n\nเพิ่มสินค้า\nชื่อสินค้า: (ชื่อสินค้า)\nราคา: (ราคาเป็นตัวเลข เช่น 60)';
