// สายค้นสินค้า — ถอดคำค้นจากประโยคที่ผู้ใช้พิมพ์
// มาถึงที่นี่เฉพาะข้อความที่ไม่ตรงคำสั่งใดเลย (ปลายสาย IF ทั้งหมด)
const p = $json;
const raw = String(p.text || '').trim();
let term = '';

const GREETING = ['สวัสดี', 'หวัดดี', 'ขอบคุณ', 'ขอบใจ', 'โอเค'];
let isGreeting = false;
for (const g of GREETING) { if (raw.indexOf(g) !== -1) { isGreeting = true; } }

const LONG = [
  'ช่วยหาให้หน่อย','ช่วยหาหน่อย','มีขายบ้างไหม','มีขายไหม','มีขายมั้ย','มีขายบ้าง',
  'อยากสั่ง','อยากได้','อยากกิน','ต้องการ','ขอซื้อ','ค้นหา','ช่วยหา','สั่งซื้อ',
  'ร้านไหน','ที่ไหน','ใกล้ฉัน','อยากจะ','ราคา','หน่อย','บ้าง','ด้วย',
  'ครับ','มีไหม','มีมั้ย','ไหม','มั้ย','ช่วย','ซื้อ','ขาย'
].sort(function (a, b) { return b.length - a.length; });

const SHORT = ['ค่ะ', 'คะ', 'ขอ', 'มี', 'หา', 'จะ'];

if (p.eventType === 'message' && raw.length > 0 && !isGreeting) {
  let s = raw;
  for (const f of LONG) { s = s.split(f).join(' '); }

  const parts = s.split(/[\s,.!?\/ๆ]+/).filter(Boolean);
  let best = '';
  for (const w of parts) { if (w.length > best.length) best = w; }

  // ตัดคำสั้นที่ติดหัวหรือท้ายออก แต่ไม่ตัดกลางคำ
  let changed = true;
  while (changed) {
    changed = false;
    for (const f of SHORT) {
      if (best.length > f.length && best.indexOf(f) === 0) { best = best.slice(f.length); changed = true; }
      if (best.length > f.length && best.slice(-f.length) === f) { best = best.slice(0, -f.length); changed = true; }
    }
  }

  if (best.length >= 2) term = best;
}

return [{ json: Object.assign({}, p, { searchTerm: term }) }];

// รวมผลค้นหาเป็นข้อความเดียว — ทำงานครั้งเดียวต่อ 1 ข้อความของผู้ใช้
const rows = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.item_id; });

const term = $('Extract Search Term').first().json.searchTerm || '';

if (!rows.length || !term) {
  return [{ json: { found: false, text: '' } }];
}

const byShop = {};
const order = [];
for (const r of rows) {
  if (!byShop[r.merchant_id]) { byShop[r.merchant_id] = { name: r.merchant_name, items: [] }; order.push(r.merchant_id); }
  if (byShop[r.merchant_id].items.length < 3) { byShop[r.merchant_id].items.push(r); }
}

const shops = order.slice(0, 5).map(function (k) { return byShop[k]; });

let text = 'พบ "' + term + '" ที่ร้านเหล่านี้ครับ\n';
for (const s of shops) {
  text += '\n' + s.name + '\n';
  for (const it of s.items) {
    text += '  - ' + it.item_name + ' ' + Math.round(Number(it.price)) + ' บาท\n';
  }
}
if (order.length > 5) { text += '\n(ยังมีอีก ' + (order.length - 5) + ' ร้าน)\n'; }
text += '\nพิมพ์ สั่งอาหาร/ของแห้ง เพื่อเริ่มสั่งซื้อได้เลยครับ';

if (text.length > 4800) { text = text.slice(0, 4800); }

return [{ json: { found: true, text: text } }];

